#[allow(unused)]
pub fn items<'a>(&'a self, cx: <T::Summary as Summary>::Context<'a>) -> Vec<T> {
    let mut items = Vec::new();
    let mut cursor = self.cursor::<()>(cx);
    cursor.next();
    while let Some(item) = cursor.item() {
        items.push(item.clone());
        cursor.next();
    }
    items
}

pub fn iter(&self) -> Iter<'_, T> {
    Iter::new(self)
